using System;

namespace Bugay.Func.Contracts;

/// <summary>
/// Discriminator for the command carried inside a <see cref="CommandEnvelope"/>.
/// A single Service Bus queue transports all three command types, so the
/// Processor uses this value to know how to deserialize and handle the payload.
/// </summary>
public enum CommandType
{
    User,
    Account,
    Transaction
}

/// <summary>Create a user. The identifier is generated by the Sender.</summary>
public sealed record CreateUserCommand(Guid Id, string FirstName, string LastName);

/// <summary>Create an account linked to a user (1:many).</summary>
public sealed record CreateAccountCommand(Guid Id, Guid UserId, string? Name);

/// <summary>
/// Create a transaction against an account. A positive <see cref="Amount"/> is an
/// increment, a negative value is a decrement.
/// </summary>
public sealed record CreateTransactionCommand(Guid Id, Guid AccountId, decimal Amount);
